import{_ as i,o as r,c as o,a2 as a}from"./chunks/framework.CAKCj7G0.js";const c=JSON.parse('{"title":"ConcurrentHashMap","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/Map/ConcurrentHashMap.md","filePath":"Java/Java/集合/Map/ConcurrentHashMap.md","lastUpdated":1762838572000}'),t={name:"Java/Java/集合/Map/ConcurrentHashMap.md"};function n(e,l,s,u,g,d){return r(),o("div",null,[...l[0]||(l[0]=[a('<h1 id="concurrenthashmap" tabindex="-1">ConcurrentHashMap <a class="header-anchor" href="#concurrenthashmap" aria-label="Permalink to &quot;ConcurrentHashMap&quot;">​</a></h1><h2 id="一、concurrenthashmap-概述" tabindex="-1">一、ConcurrentHashMap 概述 <a class="header-anchor" href="#一、concurrenthashmap-概述" aria-label="Permalink to &quot;一、ConcurrentHashMap 概述&quot;">​</a></h2><ul><li><strong>定义</strong>：<code>java.util.concurrent.ConcurrentHashMap</code> 是 Java 并发包提供的线程安全的哈希表实现，专为高并发场景设计</li><li><strong>继承关系</strong>：继承自 <code>AbstractMap</code>，实现了 <code>ConcurrentMap</code>、<code>Serializable</code> 接口</li><li><strong>核心特点</strong>： <ul><li>线程安全（比 Hashtable 更高效的并发实现）</li><li>支持高并发读写操作</li><li>允许 null 值，但不允许 null 键</li><li>无序存储（插入顺序与遍历顺序不一致）</li></ul></li></ul><h2 id="二、不同版本的实现差异" tabindex="-1">二、不同版本的实现差异 <a class="header-anchor" href="#二、不同版本的实现差异" aria-label="Permalink to &quot;二、不同版本的实现差异&quot;">​</a></h2><h3 id="_1-jdk-7-实现" tabindex="-1">1. JDK 7 实现 <a class="header-anchor" href="#_1-jdk-7-实现" aria-label="Permalink to &quot;1. JDK 7 实现&quot;">​</a></h3><ul><li><strong>分段锁机制</strong>： <ul><li>将哈希表分为多个 Segment（段），默认有16个段</li><li>每个 Segment 是一个独立的哈希表，有自己的锁</li><li>不同段之间的操作可以并行执行</li></ul></li><li><strong>结构</strong>：<code>Segment[]</code> + <code>HashEntry[]</code> + 链表</li></ul><h3 id="_2-jdk-8-实现" tabindex="-1">2. JDK 8+ 实现 <a class="header-anchor" href="#_2-jdk-8-实现" aria-label="Permalink to &quot;2. JDK 8+ 实现&quot;">​</a></h3><ul><li><strong>CAS + synchronized 机制</strong>： <ul><li>放弃了 Segment 纬度的锁，采用更细粒度的锁</li><li>使用 CAS 操作进行无锁更新</li><li>仅在必要时（如链表头节点）使用 synchronized</li></ul></li><li><strong>结构</strong>：Node[] + 链表/红黑树（与 HashMap 类似）</li></ul><h2 id="三、jdk-8-核心数据结构" tabindex="-1">三、JDK 8+ 核心数据结构 <a class="header-anchor" href="#三、jdk-8-核心数据结构" aria-label="Permalink to &quot;三、JDK 8+ 核心数据结构&quot;">​</a></h2><h3 id="_1-基本结构" tabindex="-1">1. 基本结构 <a class="header-anchor" href="#_1-基本结构" aria-label="Permalink to &quot;1. 基本结构&quot;">​</a></h3><ul><li><strong>Node 数组</strong>：作为哈希桶数组</li><li><strong>链表</strong>：处理哈希冲突</li><li><strong>红黑树</strong>：当链表长度超过阈值（8）时转换为红黑树</li></ul><h3 id="_2-核心节点类型" tabindex="-1">2. 核心节点类型 <a class="header-anchor" href="#_2-核心节点类型" aria-label="Permalink to &quot;2. 核心节点类型&quot;">​</a></h3><ul><li><strong>Node</strong>：基础存储节点，val 和 next 字段使用 volatile 保证可见性</li><li><strong>TreeNode</strong>：红黑树节点，用于高效查询</li><li><strong>ForwardingNode</strong>：扩容标记节点，指向新表，引导线程访问新表</li></ul><h2 id="四、核心参数与构造函数" tabindex="-1">四、核心参数与构造函数 <a class="header-anchor" href="#四、核心参数与构造函数" aria-label="Permalink to &quot;四、核心参数与构造函数&quot;">​</a></h2><h3 id="_1-关键参数" tabindex="-1">1. 关键参数 <a class="header-anchor" href="#_1-关键参数" aria-label="Permalink to &quot;1. 关键参数&quot;">​</a></h3><p>ConcurrentHashMap 的主要参数控制容量、并发度和性能（JDK 8+版本）：</p><ul><li><strong>初始容量</strong>：默认 16，是Node数组的初始大小（JDK 7中Node数组默认容量也是16），建议根据预期数据量设置</li><li><strong>并发等级</strong>：JDK 7特有参数，控制Segment的数量，默认16，用于设置并发线程数的预估上限（JDK 8中已移除，因为不再使用分段锁机制）</li><li><strong>负载因子</strong>：默认 0.75，平衡空间利用率和查询性能</li><li><strong>树化阈值</strong>：链表转红黑树的长度阈值，默认 8</li><li><strong>反树化阈值</strong>：红黑树转回链表的长度阈值，默认 6</li><li><strong>最小树化容量</strong>：表需要达到此容量才会进行树化，默认 64</li><li><strong>sizeCtl</strong>：内部核心控制参数，用于控制初始化和扩容，不同取值有不同含义： <ul><li>0：表示未初始化</li><li>正数：表示下次扩容的阈值（当元素数量超过此值时触发扩容）</li><li>负数：表示正在进行初始化或扩容操作，高位部分表示扩容戳，低位部分表示参与扩容的线程数</li></ul></li></ul><h3 id="_2-主要构造函数" tabindex="-1">2. 主要构造函数 <a class="header-anchor" href="#_2-主要构造函数" aria-label="Permalink to &quot;2. 主要构造函数&quot;">​</a></h3><p>提供多种构造函数以满足不同初始化需求：</p><ul><li>无参构造：使用默认参数</li><li>指定初始容量</li><li>从其他 Map 初始化</li><li>同时指定容量、负载因子和并发等级</li></ul><h2 id="五、jdk-8-关键方法实现原理" tabindex="-1">五、JDK 8+ 关键方法实现原理 <a class="header-anchor" href="#五、jdk-8-关键方法实现原理" aria-label="Permalink to &quot;五、JDK 8+ 关键方法实现原理&quot;">​</a></h2><h3 id="_1-put-方法" tabindex="-1">1. put 方法 <a class="header-anchor" href="#_1-put-方法" aria-label="Permalink to &quot;1. put 方法&quot;">​</a></h3><p>put 方法的核心流程：</p><ol><li><strong>检查参数</strong>：不允许键值为 null</li><li><strong>计算哈希</strong>：使用 spread 算法处理哈希码</li><li><strong>检查表初始化</strong>：未初始化则调用 initTable() 初始化</li><li><strong>插入数据</strong>： <ul><li>桶为空：使用 CAS 操作直接插入</li><li>表在扩容：参与扩容（帮助迁移数据），然后在<strong>当前操作的桶迁移完成后</strong>将新数据插入到正确的位置</li><li>正常插入：锁定桶的头节点，根据节点类型执行链表或红黑树操作</li></ul></li><li><strong>可能的树化</strong>：链表长度超过阈值时转为红黑树</li><li><strong>扩容检查</strong>：数据插入完成后，检查元素总数是否超过 sizeCtl（扩容阈值），如果超过则触发扩容</li></ol><p>核心特点：仅锁定当前操作的桶，而非整个表，提高并发性能，扩容触发时机在数据插入完成后</p><h3 id="_2-get-方法" tabindex="-1">2. get 方法 <a class="header-anchor" href="#_2-get-方法" aria-label="Permalink to &quot;2. get 方法&quot;">​</a></h3><p>get 方法实现简洁高效：</p><ol><li><strong>计算哈希</strong>：确定目标桶位置</li><li><strong>直接查询</strong>：无需加锁，根据节点类型进行查找</li><li><strong>三种情况</strong>： <ul><li>头节点匹配：直接返回</li><li>红黑树节点：调用 find 方法查找</li><li>链表节点：遍历链表查找</li></ul></li></ol><p>特点：无锁设计，读操作不会阻塞，性能优秀</p><h3 id="_3-扩容机制" tabindex="-1">3. 扩容机制 <a class="header-anchor" href="#_3-扩容机制" aria-label="Permalink to &quot;3. 扩容机制&quot;">​</a></h3><p>ConcurrentHashMap 采用<strong>并发扩容</strong>设计，具体扩容时机和流程如下：</p><ol><li><p><strong>触发条件</strong>：</p><ul><li>当元素总数超过阈值（容量 * 负载因子）时触发扩容，具体来说，当 put 操作导致元素数量超过 sizeCtl 时触发</li></ul></li><li><p><strong>扩容流程</strong>：</p><ul><li>创建新表（容量翻倍）</li><li>使用 ForwardingNode 标记已处理桶</li><li>多线程协作迁移数据，每个线程处理一部分桶</li></ul></li><li><p><strong>关键机制</strong>：</p><ul><li>工作窃取：未分配的桶可被其他线程处理</li><li>标记转发：已迁移桶的查询会转发到新表</li><li>帮助扩容：其他线程发现正在扩容时会主动参与迁移工作</li></ul></li></ol><h2 id="六、线程安全机制" tabindex="-1">六、线程安全机制 <a class="header-anchor" href="#六、线程安全机制" aria-label="Permalink to &quot;六、线程安全机制&quot;">​</a></h2><h3 id="_1-jdk-7-线程安全-分段锁" tabindex="-1">1. JDK 7 线程安全：分段锁 <a class="header-anchor" href="#_1-jdk-7-线程安全-分段锁" aria-label="Permalink to &quot;1. JDK 7 线程安全：分段锁&quot;">​</a></h3><ul><li>将整个哈希表分为多个 Segment</li><li>每个 Segment 独立加锁，互不影响</li><li>不同 Segment 上的操作可以并行执行</li><li>缺点： <ul><li>内存占用较大（每个 Segment 都有独立的数组和锁）</li><li>并发度受限于 Segment 数量</li></ul></li></ul><h3 id="_2-jdk-8-线程安全-cas-synchronized" tabindex="-1">2. JDK 8+ 线程安全：CAS + synchronized <a class="header-anchor" href="#_2-jdk-8-线程安全-cas-synchronized" aria-label="Permalink to &quot;2. JDK 8+ 线程安全：CAS + synchronized&quot;">​</a></h3><p>JDK 8+的ConcurrentHashMap采用了更先进的并发控制机制，结合了无锁操作和细粒度锁定，大幅提升了并发性能：</p><h4 id="核心机制详解" tabindex="-1">核心机制详解 <a class="header-anchor" href="#核心机制详解" aria-label="Permalink to &quot;核心机制详解&quot;">​</a></h4><ul><li><p><strong>CAS (Compare-And-Swap) 无锁操作</strong>：</p><ul><li><strong>原理</strong>：基于CPU原子指令实现的乐观锁，通过比较内存值与预期值，若相等则更新并返回成功</li><li><strong>应用场景</strong>：数组初始化、插入空桶、更新计数等简单操作</li><li><strong>实现</strong>：使用<code>Unsafe</code>类的<code>compareAndSwapObject</code>、<code>compareAndSwapInt</code>等方法</li><li><strong>优势</strong>：无阻塞、无上下文切换开销，高并发下性能优秀</li></ul></li><li><p><strong>synchronized 细粒度锁</strong>：</p><ul><li><strong>锁定范围</strong>：仅在必要时锁定链表头节点或红黑树根节点</li><li><strong>锁粒度</strong>：比JDK 7的Segment锁更细，从段级别缩小到桶级别</li><li><strong>进化</strong>：JDK 8中synchronized已进行优化（偏向锁、轻量级锁、重量级锁），性能开销显著降低</li><li><strong>使用时机</strong>：主要用于处理哈希冲突时的链表/红黑树操作，如节点插入、删除等</li></ul></li><li><p><strong>volatile 内存可见性</strong>：</p><ul><li><strong>应用</strong>：Node节点的val和next字段使用volatile修饰</li><li><strong>作用</strong>：确保多线程之间的数据可见性，一个线程修改后立即对其他线程可见</li><li><strong>配合CAS</strong>：为无锁操作提供可靠的内存语义保证</li></ul></li><li><p><strong>桶级锁定策略</strong>：</p><ul><li><strong>锁定单位</strong>：仅锁定正在操作的哈希桶，而非整个表或段</li><li><strong>并发粒度</strong>：不同桶上的操作完全并行，同一桶上的操作串行</li><li><strong>锁竞争</strong>：只有当多个线程访问同一个哈希桶时才会发生锁竞争</li><li><strong>实际效果</strong>：在哈希分布均匀的情况下，锁竞争概率极低</li></ul></li><li><p><strong>帮助扩容机制</strong>：</p><ul><li><strong>设计思想</strong>：将扩容任务分散给多个线程，加速扩容过程</li><li><strong>工作原理</strong>：当线程发现表正在扩容时，会检查自己要操作的桶是否已迁移 <ul><li>未迁移：参与扩容，帮助迁移数据</li><li>已迁移：直接在新表上操作</li></ul></li><li><strong>同步协调</strong>：使用ForwardingNode节点标记已完成迁移的桶</li><li><strong>性能影响</strong>：通过多线程并行工作，显著减少扩容对正常操作的影响</li></ul></li></ul><h4 id="与jdk-7分段锁的对比优势" tabindex="-1">与JDK 7分段锁的对比优势 <a class="header-anchor" href="#与jdk-7分段锁的对比优势" aria-label="Permalink to &quot;与JDK 7分段锁的对比优势&quot;">​</a></h4><ul><li><strong>更高的并发度</strong>：桶级锁比Segment锁粒度更细，理论并发度可达到数组长度级别</li><li><strong>更好的内存利用率</strong>：无需为每个段维护独立的数组和锁结构</li><li><strong>更灵活的锁策略</strong>：根据操作类型动态选择无锁(CAS)或有锁(synchronized)操作</li><li><strong>更高效的扩容机制</strong>：多线程并行扩容，避免扩容过程成为性能瓶颈</li><li><strong>更好的伸缩性</strong>：随着容器大小增长，并发性能不会明显下降（不会受限于固定数量的Segment）</li></ul><p>这种混合使用CAS、synchronized和volatile的设计，充分发挥了各种并发控制机制的优势，使ConcurrentHashMap在保证线程安全的同时，提供了接近HashMap的性能表现。</p><h2 id="七、使用注意事项" tabindex="-1">七、使用注意事项 <a class="header-anchor" href="#七、使用注意事项" aria-label="Permalink to &quot;七、使用注意事项&quot;">​</a></h2><ol><li><p><strong>null 值处理</strong>：</p><ul><li>不允许使用 null 作为键</li><li>允许使用 null 作为值</li></ul></li><li><p><strong>线程安全保证</strong>：</p><ul><li>get 操作不阻塞（读不加锁）</li><li>迭代器弱一致性（不会抛出 ConcurrentModificationException）</li><li>不保证原子性复合操作（如 putIfAbsent 是原子的，但 putAll 不是）</li></ul></li><li><p><strong>性能调优</strong>：</p><ul><li>初始容量设置：根据预期并发级别和元素数量</li><li>避免热点键：尽量使键的哈希分布均匀</li><li>减少锁竞争：避免频繁修改同一键值对</li></ul></li><li><p><strong>原子操作支持</strong>：</p><ul><li>ConcurrentHashMap 实现了 ConcurrentMap 接口，提供了额外的原子操作： <ul><li><code>putIfAbsent(K key, V value)</code>：仅当键不存在时才插入</li><li><code>remove(Object key, Object value)</code>：仅当键值匹配时才删除</li><li><code>replace(K key, V oldValue, V newValue)</code>：仅当旧值匹配时才替换</li></ul></li></ul></li></ol><h2 id="八、常见问题" tabindex="-1">八、常见问题 <a class="header-anchor" href="#八、常见问题" aria-label="Permalink to &quot;八、常见问题&quot;">​</a></h2><ol><li><p><strong>为什么不允许 null 键？</strong></p><ul><li>避免歧义：get 返回 null 时，无法区分键不存在还是值为 null</li><li>符合 ConcurrentMap 接口规范</li></ul></li><li><p><strong>弱一致性迭代器意味着什么？</strong></p><ul><li>修改不会抛出 ConcurrentModificationException</li><li>不一定反映最新状态</li><li>适合并发读取场景</li></ul></li><li><p><strong>如何避免死锁？</strong></p><ul><li>CAS 操作和细粒度锁避免嵌套锁定</li><li>ForwardingNode 协调多线程扩容</li></ul></li><li><p><strong>size 方法是否准确？</strong></p><ul><li>非完全准确，返回估计值</li><li>并发环境下计数可能变化</li><li>精确计数需额外同步</li></ul></li><li><p><strong>如何选择并发集合？</strong></p><ul><li>Map：ConcurrentHashMap</li><li>List/Set（读多写少）：CopyOnWriteArrayList/CopyOnWriteArraySet</li><li>队列：ConcurrentLinkedQueue（无界非阻塞）、LinkedBlockingQueue（有界阻塞）</li></ul></li></ol>',46)])])}const p=i(t,[["render",n]]);export{c as __pageData,p as default};
